// Shell completion artifacts generated by Ghostty's compile-time generators.
//
// Translated from ghostty/src/extra/{bash,fish,zsh}.zig. Those files expose
// compile-time string constants. V cannot correctly reflect over Config's
// large set of optional enum fields, so the equivalent constants are embedded
// from the pinned source generator's byte-for-byte output.
module extra

const bash_completion_data = $embed_file('bash_completion.txt').to_string()
const fish_completion_data = $embed_file('fish_completion.txt').to_string()
const zsh_completion_data = $embed_file('zsh_completion.txt').to_string()

// bash_completions returns Ghostty's generated Bash completion script.
pub fn bash_completions() string {
	return bash_completion_data
}

// fish_completions returns Ghostty's generated Fish completion script.
pub fn fish_completions() string {
	return fish_completion_data
}

// zsh_completions returns Ghostty's generated Zsh completion script.
pub fn zsh_completions() string {
	return zsh_completion_data
}
